import{_ as e,o as i,c as a,a7 as s}from"./chunks/framework.DUCm5Bu5.js";const k=JSON.parse('{"title":"參與貢獻","description":"設定工具鏈、建置與測試、遵循專案規則，並提交可審查的改動。","frontmatter":{"title":"參與貢獻","description":"設定工具鏈、建置與測試、遵循專案規則，並提交可審查的改動。","updated":"2026-10-18T00:00:00.000Z"},"headers":[],"relativePath":"zh-tw/project/contributing.md","filePath":"zh-tw/project/contributing.md"}'),d={name:"zh-tw/project/contributing.md"};function o(l,t,c,n,h,r){return i(),a("div",null,[...t[0]||(t[0]=[s(`<h2 id="本頁內容" tabindex="-1">本頁內容 <a class="header-anchor" href="#本頁內容" aria-label="Permalink to &quot;本頁內容&quot;">​</a></h2><p>本頁帶新貢獻者從一台乾淨的機器走到一個可審查、可合併的改動：先讀哪些規則、需要什麼工具鏈、建置與驗證命令、儲存庫結構、改動附帶的責任，以及審查流程。Bubble Fighter Fantasy 是由 Fantasy Tale Studio 維護的預發行社群伺服器，使用 C# 與 .NET 10 撰寫，並由模組組合而成。</p><p><strong>適用對象。</strong> 首次貢獻的人，以及需要重現或審查他人改動的貢獻者。</p><p><strong>開始之前。</strong></p><ul><li>閱讀儲存庫根目錄的 <code>AGENTS.md</code> 與 <code>CONTRIBUTING.md</code>。<code>AGENTS.md</code> 具有約束力，包含架構、packet 資料、證據、命名與語言規則。</li><li>安裝 .NET 10 SDK 與 Git；建置並執行伺服器需要這兩者。</li><li>真實遊戲用戶端及其資料只在原生用戶端測試時需要。儲存庫本身不包含它們。</li></ul><h2 id="先讀規則" tabindex="-1">先讀規則 <a class="header-anchor" href="#先讀規則" aria-label="Permalink to &quot;先讀規則&quot;">​</a></h2><table tabindex="0"><thead><tr><th>規則</th><th>實際意義</th></tr></thead><tbody><tr><td>一切都是模組</td><td>新能力以 profile 中的模組資料列形式交付，而不是核心或 Host 中的特例。</td></tr><tr><td>Context 是服務登錄</td><td>只透過宣告的介面型別消費服務，不要存取其他模組的具體類別。</td></tr><tr><td>註冊即 effect</td><td>每個 <code>Register*</code>/<code>On*</code> 都傳回可處置控制代碼，交給 <code>context.Effect(...)</code>，卸載時依相反順序回退。</td></tr><tr><td>不允許硬編碼可調參數</td><td>隨部署變化的值是模組資料列上經過驗證的設定欄位，而不是常數。</td></tr><tr><td>失敗要響亮</td><td>錯誤設定、缺少服務、畸形 packet 與連線失敗都是錯誤，絕不靜默使用預設值。</td></tr><tr><td>資源必須有界</td><td>不允許無界佇列、緩衝區或檔案寫入；溢位要回報，且不能拖住遊戲。</td></tr><tr><td>packet 佈局是資料</td><td>結構寫在 <code>packets/</code> 中，以基線寫一次並依建置註解；程式碼依欄位名稱提供值。</td></tr><tr><td>證據來自用戶端</td><td>佈局與順序透過閱讀用戶端自身程式碼確定，每項結論保留帶建置前綴的函式位址。</td></tr><tr><td>程式碼使用英文</td><td>程式碼、註解、XML 文件、提交訊息、<code>opcodes.yaml</code> 與 <code>profiles/opcode-policy.md</code> 使用英文。</td></tr><tr><td>使用者文件雙語</td><td>英文指南與其中文翻譯在同一次提交中更新。站台頁面還需要繁體中文與韓文。</td></tr></tbody></table><p>任何地方都不要使用 emoji。不要引用或提及第三方專案、其他伺服器或參考樹；用本專案自己的術語描述設計。</p><h2 id="設定工具鏈" tabindex="-1">設定工具鏈 <a class="header-anchor" href="#設定工具鏈" aria-label="Permalink to &quot;設定工具鏈&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>用途</th><th>檢查</th></tr></thead><tbody><tr><td>.NET 10 SDK</td><td>建置與執行伺服器</td><td><code>dotnet --version</code> 顯示 10.x</td></tr><tr><td>Git</td><td>複製、分支、驗證關卡</td><td><code>git --version</code></td></tr><tr><td>Python 3</td><td>CI 關卡指令碼及其單元測試</td><td><code>python --version</code></td></tr><tr><td>Node.js 與 npm</td><td>文件站、TypeScript SDK 一致性</td><td><code>node --version</code>、<code>npm --version</code></td></tr><tr><td>Go</td><td>Go SDK 一致性檢查與測試</td><td><code>go version</code></td></tr><tr><td>Rust 與 cargo、rustup，以及 <code>wasm32-wasip1</code></td><td>Rust SDK 一致性與 WebAssembly 測試</td><td><code>rustc --version</code>；<code>rustup target add wasm32-wasip1</code></td></tr></tbody></table><p>建置並執行伺服器只需要 .NET 與 Git。其餘工具鏈供驗證關卡、文件站與 SDK 測試套件使用；缺少時關卡會回報，而不是靜默略過。</p><p>在 PowerShell 或 shell 中，從應放置檢出的目錄執行：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/Wasabi-FantasyTaleDev/BubbleFighter.Fantasy.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> BubbleFighter.Fantasy</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dotnet</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> BubbleFighter.Fantasy.sln</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Release</span></span></code></pre></div><p><strong>確認成功。</strong> 複製目錄包含 <code>BubbleFighter.Fantasy.sln</code>，建置以 <code>0 Warning(s)</code> 和 <code>0 Error(s)</code> 結束。</p><h2 id="本機建置與測試" tabindex="-1">本機建置與測試 <a class="header-anchor" href="#本機建置與測試" aria-label="Permalink to &quot;本機建置與測試&quot;">​</a></h2><h3 id="建置方案" tabindex="-1">建置方案 <a class="header-anchor" href="#建置方案" aria-label="Permalink to &quot;建置方案&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dotnet</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> BubbleFighter.Fantasy.sln</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Release</span></span></code></pre></div><p>警告即錯誤（<code>TreatWarningsAsErrors</code> 已啟用），且 <code>GenerateDocumentationFile</code> 要求每個公開型別與成員都有有意義的 XML 摘要。修正原因，絕不要為了讓建置變綠而停用警告。</p><h3 id="執行測試專案" tabindex="-1">執行測試專案 <a class="header-anchor" href="#執行測試專案" aria-label="Permalink to &quot;執行測試專案&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dotnet</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> BubbleFighter.Fantasy.sln</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Release</span></span></code></pre></div><p>這是開發時的快速循環。發行關卡並不直接使用它：關卡以 <code>git ls-files tests/*/*.csproj</code> 發現每個被追蹤的測試專案（包括方案之外的），並逐一序列執行，每個專案一份 TRX。每次嘗試使用獨立的結果目錄或檔名，避免重跑覆蓋先前的失敗。</p><h3 id="執行關卡自測" tabindex="-1">執行關卡自測 <a class="header-anchor" href="#執行關卡自測" aria-label="Permalink to &quot;執行關卡自測&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unittest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> discover</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/ci</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;test_*.py&quot;</span></span></code></pre></div><p>這些測試保護關卡執行器本身，防止空報告、缺少報告或被略過的報告被誤報為成功。</p><h3 id="執行公開關卡" tabindex="-1">執行公開關卡 <a class="header-anchor" href="#執行公開關卡" aria-label="Permalink to &quot;執行公開關卡&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/ci/serial-gates.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --public</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --results-directory</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artifacts/validation/public-01</span></span></code></pre></div><p>每次嘗試都使用新的、不存在的結果目錄——執行器拒絕已存在的目錄。它會建置 Release、執行 SDK 一致性檢查、逐一序列執行測試專案、檢查 packet 表，並傾印帶隔離修補檔的 <code>kr-1256</code> 設定。最後輸出 <code>PASS public gates: &lt;n&gt; populated test reports, &lt;n&gt; tests, no skips</code>，並把排除範圍記錄到 <code>scope.json</code>。公開模式執行每個被追蹤的測試專案，只排除 <code>Category=LocalClientData</code> 案例；它不是完整發行關卡。如果設定了 <code>CI=true</code>，執行器還會拒絕含有 <code>.env</code> 或 <code>profiles/*/local.patch.yaml</code> 的檢出。</p><p><strong>確認成功。</strong> 結束碼為 0，最後一行是上面的 <code>PASS</code> 行。非零結束會印出 <code>FAIL &lt;reason&gt;</code>；失敗步驟的記錄在結果目錄中。</p><h3 id="執行本機-host-檢查" tabindex="-1">執行本機 Host 檢查 <a class="header-anchor" href="#執行本機-host-檢查" aria-label="Permalink to &quot;執行本機 Host 檢查&quot;">​</a></h3><p>遵循<a href="./../getting-started/quickstart">快速開始</a>：將 <code>.env.example</code> 複製為 <code>.env</code>，把 <code>BFF_MYSQL_PASSWORD</code> 設為非空的臨時值，並且一律加上隔離修補檔——<code>--dump-config</code> 也一樣：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dotnet</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/BubbleFighter.Fantasy.Host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> management</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --patch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/local-checks/isolated-memory.patch.yaml</span></span></code></pre></div><p>該修補檔停用 <code>persistence.mysql</code> 並啟用記憶體持久化，因此開發者的 <code>.env</code> 或本機覆寫不會連線真實資料庫。絕不要把測試或本機檢查指向生產資料庫。<strong>確認成功：</strong> 另一個終端機從 <code>http://127.0.0.1:8080/health</code> 得到 <code>{&quot;status&quot;:&quot;ok&quot;, ...}</code>；用 Ctrl+C 停止。</p><h2 id="儲存庫結構" tabindex="-1">儲存庫結構 <a class="header-anchor" href="#儲存庫結構" aria-label="Permalink to &quot;儲存庫結構&quot;">​</a></h2><table tabindex="0"><thead><tr><th>路徑</th><th>內容</th></tr></thead><tbody><tr><td><code>src/BubbleFighter.Fantasy.Abstractions</code>、<code>src/BubbleFighter.Fantasy.Contracts</code></td><td>共用模組契約；由 Host 載入一次並共用給每個模組</td></tr><tr><td><code>src/BubbleFighter.Fantasy.Kernel</code></td><td>模組執行階段：探索、啟用、服務登錄、effect、profile 組合</td></tr><tr><td><code>src/BubbleFighter.Fantasy.Host</code></td><td><code>bff</code> 主控台 Host 及其 bootstrap profile</td></tr><tr><td><code>src/Plugins/</code></td><td>監聽器、方言、遊戲功能、持久化、管理與 SDK loader</td></tr><tr><td><code>profiles/</code></td><td>profile 資料列、bundle、修補檔與逐建置 opcode 表</td></tr><tr><td><code>packets/</code></td><td>packet 佈局資料與逐建置繼承</td></tr><tr><td><code>sdk/</code></td><td>可選的 Python、TypeScript、Go 與 Rust 模組 SDK</td></tr><tr><td><code>tests/</code></td><td>.NET 測試專案與共用 fixture</td></tr><tr><td><code>tools/</code></td><td>驗證關卡（<code>tools/ci</code>）、本機檢查修補檔（<code>tools/local-checks</code>）與維護指令碼</td></tr><tr><td><code>docs/</code></td><td>已發布指南的來源</td></tr><tr><td><code>docs-site/</code></td><td>VitePress 站台、頁面清單與內容同步</td></tr><tr><td><code>deploy/</code></td><td>Docker 檔案與 Compose 範本</td></tr></tbody></table><h2 id="進行改動" tabindex="-1">進行改動 <a class="header-anchor" href="#進行改動" aria-label="Permalink to &quot;進行改動&quot;">​</a></h2><h3 id="分支與拆分工作" tabindex="-1">分支與拆分工作 <a class="header-anchor" href="#分支與拆分工作" aria-label="Permalink to &quot;分支與拆分工作&quot;">​</a></h3><p>在自己的分支上工作，一次提交只做一個邏輯改動；改動經審查後才進入 <code>main</code>。提交訊息使用英文：改了什麼、為什麼改、有什麼證據支持。</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> switch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fix/short-topic</span></span></code></pre></div><h3 id="提供證據" tabindex="-1">提供證據 <a class="header-anchor" href="#提供證據" aria-label="Permalink to &quot;提供證據&quot;">​</a></h3><ul><li>隨改動新增或更新測試。packet 改動要加位元組釘住測試，做到改動前失敗、改動後通過。</li><li>先執行目標測試，再執行完整建置與測試。保留先前失敗嘗試的輸出，不要被重跑覆蓋。</li><li>依程式碼中的方式引用證據：wire 結論使用帶建置前綴的用戶端函式位址（<code>kr-812 sub_810C20</code>）。</li><li>在改動說明中寫明執行了什麼、能證明什麼；自動化測試不能證明真實用戶端相容性。</li></ul><h3 id="遵循模組與資源規則" tabindex="-1">遵循模組與資源規則 <a class="header-anchor" href="#遵循模組與資源規則" aria-label="Permalink to &quot;遵循模組與資源規則&quot;">​</a></h3><ul><li>以模組資料列新增能力：在 <code>[Plugin(...)]</code> 中宣告所需與提供的介面，透過 <code>IPluginContext</code> 消費，並且只透過它註冊。</li><li>每個註冊與外部資源都用 effect 持有，使卸載時可以回退；不要留下無界背景工作或佇列。</li><li>把隨部署變化的值放進該資料列經過驗證的選項類別（<code>[Required]</code>、<code>[Range]</code>、<code>IValidatableOptions</code>），而不是常數。</li><li>以共用契約組件建置；不要把 <code>Abstractions</code> 與 <code>Contracts</code> 的私有副本隨模組發布。</li><li>公開型別與成員都要有真實的 XML 摘要。註解說明原因，並指向證據。</li></ul><h3 id="修改-packet-或-opcode-資料" tabindex="-1">修改 packet 或 opcode 資料 <a class="header-anchor" href="#修改-packet-或-opcode-資料" aria-label="Permalink to &quot;修改 packet 或 opcode 資料&quot;">​</a></h3><p>改動佈局前先讀 <code>packets/README.md</code> 與 <code>profiles/opcode-policy.md</code>。簡要規則：</p><ul><li>每個結構以 <code>kr-812</code> 基線寫一次，一行一個具名欄位並標註用戶端位移；有差異的建置在該列上加註解（<code>except</code>、<code>only</code>、<code>also</code>，或自己的取代）。表能表達的內容，絕不要在程式碼裡加逐建置欄位表或 <code>if (build ...)</code>。</li><li>用途未經證實的欄位保持 <code>unknown_&lt;offset&gt;</code>；不要臆造含義。每個 <code>sub_</code> 位址都帶用戶端建置前綴。</li><li>opcode 列記錄 <code>verified</code>、<code>inferred</code>、<code>unverified</code> 或 <code>observed-session</code> 證據等級與 <code>name_source</code>；未知入站 opcode 只寫入記錄，絕不樂觀解析。C2S 與 S2C、遊戲與 relay 連線是各自獨立的空間。</li><li>每個 codec 都需要位元組長度釘住測試；wire 改動在提交前要對照用戶端消費路徑檢查。</li><li>用 <code>bff packets show &lt;build&gt; &lt;structure&gt;</code>、<code>bff packets diff &lt;build&gt; &lt;build&gt;</code> 與 <code>bff packets check</code> 核對表。</li></ul><h2 id="文件改動" tabindex="-1">文件改動 <a class="header-anchor" href="#文件改動" aria-label="Permalink to &quot;文件改動&quot;">​</a></h2><p><code>docs/</code> 是已發布指南的來源；<code>docs-site/</code> 透過 <code>docs-site/pages.json</code> 中的明確頁面清單建置站台。每個已發布頁面有四個檔案——<code>X.md</code>（英文，權威版本）、<code>X.zh.md</code>、<code>X.zh-tw.md</code> 與 <code>X.ko.md</code>——每個檔案都需要包含 <code>title</code>、<code>description</code> 與 <code>updated</code> 日期的 front matter。</p><ul><li>本機連結必須指向已發布的頁面來源，例如<a href="./../guides/configuration">設定伺服器</a>。外部 URL 與錨點可以保留。</li><li>不要編輯 <code>docs-site/content/</code> 下產生的內容，也不要提交建置產物；兩者都被忽略。</li><li>英文與中文指南要一起更新，並保持站台頁面四種翻譯同步。</li><li>在同一次提交中為兩份根目錄更新紀錄（<code>CHANGELOG.md</code> 與 <code>CHANGELOG.zh.md</code>）新增帶日期的條目；日期格式為 <code>YYYY-MM-DD</code>，註明時間時使用 Asia/Shanghai。新條目放在舊條目上方。</li></ul><p>在站台目錄中建置：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs-site</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p>同步步驟在建置前執行，驗證中繼資料與連結。front matter 不完整時以 <code>Missing guide metadata: &lt;path&gt;</code> 失敗，缺少四個檔案之一時以 <code>Missing public guide: &lt;path&gt;</code> 失敗，本機連結未指向已發布頁面時以 <code>Unpublished local link: &lt;target&gt;</code> 失敗。可以參考其他已發布指南，例如<a href="./../guides/configuration">設定</a>與<a href="./../guides/plugins">模組</a>。</p><h2 id="驗證等級" tabindex="-1">驗證等級 <a class="header-anchor" href="#驗證等級" aria-label="Permalink to &quot;驗證等級&quot;">​</a></h2><table tabindex="0"><thead><tr><th>等級</th><th>執行內容</th><th>需要</th><th>證明什麼</th></tr></thead><tbody><tr><td>快速</td><td><code>dotnet build</code> 與 <code>dotnet test</code></td><td>.NET</td><td>改動可編譯，.NET 測試套件通過</td></tr><tr><td>公開關卡</td><td><code>tools/ci/serial-gates.py --public</code></td><td>.NET、Python、Node.js/npm、Go、Rust 與 <code>wasm32-wasip1</code></td><td>除本機資料案例外每個被追蹤測試專案、SDK 一致性、packet 表、隔離設定</td></tr><tr><td>完整關卡</td><td>同一命令去掉 <code>--public</code></td><td>下列本機用戶端工作簿</td><td>全部測試、無略過；這是發行關卡</td></tr><tr><td>發行審查</td><td>隔離啟動與受影響的真實用戶端流程</td><td>真實遊戲用戶端</td><td>用戶端驗收；任何自動檢查都無法替代</td></tr></tbody></table><p>完整關卡需要以下本機取得的用戶端檔案；它們不隨儲存庫散布：</p><table tabindex="0"><thead><tr><th>設定或路徑</th><th>必要檔案</th></tr></thead><tbody><tr><td><code>client-data/cn-324/</code></td><td><code>Config/ShopItem2.xml</code></td></tr><tr><td><code>client-data/kr-1256/data/</code></td><td><code>Packs/Config_00000.pkn</code>（商店與角色工作簿）與 <code>Packs/ConfigSh_00000.pkn</code>（寵物疊加表）</td></tr><tr><td><code>artifacts/shop-tables-survey/id400/xml/</code></td><td><code>Config/ShopItem2.xml</code></td></tr></tbody></table><p>如果檔案缺少，完整關卡會列出缺少的前置條件並停止：<code>Local game data is missing for &lt;tests&gt;; provision it or pass --public to run the publicly reproducible gates only.</code></p><p>如實回報驗證結果：</p><ul><li>每次嘗試使用新的結果目錄；有內容的 TRX 必須與全部通過的計數一致，沒有失敗、空結果或略過結果。被略過的測試不算通過。</li><li>回報你實際執行的模式。公開關卡把排除範圍寫入 <code>scope.json</code>，它不是完整發行關卡。</li><li>不要刪除或改寫失敗結果。保留失敗嘗試的主控台記錄與 TRX。</li><li>說明結果來自自動檢查還是真實遊戲用戶端。</li></ul><p>公開儲存庫工作流程在 GitHub 託管的 Windows 執行器上，為 <code>main</code> 的推送與 pull request 執行可公開重現的關卡；它不執行本機資料用例。有本機用戶端資料前置條件時，請在本機執行完整關卡，並讓 CI 檢出保持不含 <code>.env</code> 與本機 profile 修補檔。</p><h2 id="可審查改動包含什麼" tabindex="-1">可審查改動包含什麼 <a class="header-anchor" href="#可審查改動包含什麼" aria-label="Permalink to &quot;可審查改動包含什麼&quot;">​</a></h2><ul><li>只做一件事的聚焦 diff，並帶有涵蓋所改行為的測試。</li><li>驗證證據：命令、結果，以及修正前曾有的失敗輸出。</li><li>改動所必需的資料與文件更新：wire 佈局的 packet 表、帶證據的 opcode 列、英文與中文指南更新、更新紀錄條目。</li><li>不包含無關的重格式化、產生檔案、建置產物、記錄或本機覆寫。</li></ul><h2 id="哪些會被拒絕" tabindex="-1">哪些會被拒絕 <a class="header-anchor" href="#哪些會被拒絕" aria-label="Permalink to &quot;哪些會被拒絕&quot;">​</a></h2><ul><li>憑證、權杖、<code>.env</code> 檔案、本機 profile 修補檔，或出現在程式碼、文件、記錄中的任何機密。</li><li>私有調查材料、擷取、反編譯用戶端匯出或用戶端資源。</li><li>第三方程式碼、抄來的佈局，或提及其他專案與伺服器名稱的引用。</li><li>猜測的 packet 名稱或欄位含義，或基於 <code>unverified</code> 證據啟用的處理常式。</li><li>無界佇列、緩衝區或檔案寫入，以及用硬編碼代替經過驗證設定的部署值。</li><li>停用警告的建置，或被略過卻回報為通過的測試。</li><li>提交產生的文件內容、建置產物，或把未合併分支中的功能描述為可用。</li></ul><h2 id="提交流程" tabindex="-1">提交流程 <a class="header-anchor" href="#提交流程" aria-label="Permalink to &quot;提交流程&quot;">​</a></h2><ol><li>推送你的分支並向 <code>main</code> 發起 pull request。</li><li>說明行為改動、證據以及所執行的驗證模式；如果改動修正缺陷，附上失敗輸出。</li><li>確認 diff 不含機密、私有材料或產生內容。</li><li>用新的提交或清楚的解釋回應審查意見；保持歷史可審查。</li><li>審查通過後合入 <code>main</code>。注意隨後一次序列驗證執行，因為工作流程在 <code>main</code> 上執行。</li></ol><h2 id="後續" tabindex="-1">後續 <a class="header-anchor" href="#後續" aria-label="Permalink to &quot;後續&quot;">​</a></h2><ul><li>專案的 GitHub 儲存庫是 README 記錄的入口：<a href="https://github.com/Wasabi-FantasyTaleDev/BubbleFighter.Fantasy" target="_blank" rel="noreferrer">https://github.com/Wasabi-FantasyTaleDev/BubbleFighter.Fantasy</a> 。儲存庫沒有記錄聊天伺服器或論壇。</li><li><a href="./../guides/configuration">設定</a> 與<a href="./../guides/plugins">模組</a> 介紹改動通常涉及的結構。</li><li><a href="./../guides/sdk-protocol">SDK 協定</a> 介紹可選語言 SDK，<a href="./../guides/troubleshooting">疑難排解</a> 幫助解決建置或關卡失敗。</li></ul>`,67)])])}const u=e(d,[["render",o]]);export{k as __pageData,u as default};
